text:
[
  {
    "outcome": "Wren pays the nine days, adding them to his 4,027 owed, repacks the pale wooden crate, and Haro waves him through the Ferrous Gate to continue down the Road.",
    "stance": "neither"
  },
  {
    "outcome": "Haro insists on actually opening the sealed crate to complete his inspection, breaking the wax seal and revealing what Wren has been carrying since the low bridges.",
    "stance": "hope"
  },
  {
    "outcome": "Wren refuses the surcharge or attempts to walk around the gate with his crate, triggering an immediate consequence from the Road that worsens his debt past 4,027 days.",
    "stance": "dread"
  }
]

[
  {
    "outcome": "Haro breaks the wax seal and opens the crate for inspection, revealing what cargo Wren has been unknowingly carrying and how long he has been entrusted with it.",
    "stance": "hope"
  },
  {
    "outcome": "Wren attempts to walk the crate around the Ferrous Gate to circumvent the toll, is caught or detected by the Road's enforcement, and incurs a dramatically worse penalty than the 9 days.",
    "stance": "dread"
  },
  {
    "outcome": "Wren accepts the 9-day toll, shoulders the crate again, and departs the Ferrous Gate toward his destination with the sealed cargo still unopened.",
    "stance": "neither"
  }
]

[
  {
    "outcome": "Wren pays the nine-day toll to Haro, who updates the ledger and marks him deeper in debt, then Wren hoists the crate back onto his frame and walks through the Ferrous Gate.",
    "stance": "neither"
  },
  {
    "outcome": "Haro breaks or opens the wax seal on the crate to conduct a true inspection, removing or checking its contents before resealing it with fresh wax.",
    "stance": "dread"
  },
  {
    "outcome": "As Wren reaches the gate threshold, someone emerges from the other side and hands him a ledger entry or sealed note indicating the crate's true destination or revealing it has a hidden owner.",
    "stance": "neither"
  }
]

[
  {
    "outcome": "Haro breaks the wax seal and opens the crate to inspect its contents, revealing what Wren has been carrying all along.",
    "stance": "hope"
  },
  {
    "outcome": "Wren refuses to pay 9 days and walks around the left upright of the Ferrous Gate instead of passing through it, triggering the Road's punishment for toll evasion.",
    "stance": "dread"
  },
  {
    "outcome": "Wren accepts the 9-day toll, the ledger is marked and his debt reduced from 4,027 to 4,018, and he continues forward through the gate with the crate still sealed.",
    "stance": "neither"
  }
]

[
  {
    "outcome": "Haro breaks the wax seal and opens the crate, revealing what Wren has been carrying—trade goods, documents, or something concrete that could be leveraged to pay the toll or given up to satisfy the inspection.",
    "stance": "hope"
  },
  {
    "outcome": "Wren produces payment from some reserve, Haro marks the ledger with 9 additional days owed, and Wren shoulders the frame again, stepping through the iron uprights with the debt now 9 days worse.",
    "stance": "neither"
  },
  {
    "outcome": "Wren refuses the extra 2 days, sets down the frame, and walks around the gate's edge instead of through it, triggering the Road's penalty—a debt that turns out to cost far more than the 9-day toll would have.",
    "stance": "dread"
  }
]

[
  {
    "outcome": "Wren produces the payment for nine days and hands it to Haro, picks up the sealed crate, and walks through the Ferrous Gate to continue down the Road.",
    "stance": "dread"
  },
  {
    "outcome": "Haro uses one of the keys on his ring to break the wax seal and opens the crate, revealing its contents for the first time.",
    "stance": "hope"
  },
  {
    "outcome": "Wren refuses to pay the two-day inspection surcharge, telling Haro it was not listed on the posted board, and stands his ground to see what Haro does next.",
    "stance": "hope"
  }
]

[
  {
    "outcome": "Haro breaks the wax seal and opens the pale wooden crate, revealing its sealed contents. Whatever is inside becomes visible.",
    "stance": "hope"
  },
  {
    "outcome": "Haro demands that Wren himself break the seal to prove the cargo, forcing Wren to violate whatever protection the seal represented and choose between breaking trust with whoever sealed it or refusing passage entirely.",
    "stance": "dread"
  },
  {
    "outcome": "The wax seal glows or burns Haro's fingers when he touches it, preventing inspection. The cargo's magic overrides his authority and he must pass Wren through.",
    "stance": "hope"
  }
]

[
  {
    "outcome": "Wren accepts the nine-day toll. Haro marks the ledger, adding nine days to Wren's debt (bringing it to 4,036 days owed against 61 days paid), and Wren hoists the sealed crate back onto his frame.",
    "stance": "dread"
  },
  {
    "outcome": "Wren refuses to pay nine days and walks around the side of the Ferrous Gate with the crate, bypassing it entirely. The System or Haro announces a penalty—a larger debt charge for breach of passage—and the ledger is marked with the violation.",
    "stance": "hope"
  },
  {
    "outcome": "Haro demands to inspect the sealed crate's contents by breaking the wax seal and opening the lid, revealing what Wren has been carrying since the low bridges. The contents either validate the surcharge or shift Wren's entire situation.",
    "stance": "neither"
  }
]

[
  {
    "outcome": "Wren shoulders the crate and walks under the Ferrous Gate. The next road has another toll-post visible in the distance, and Haro's closing words—something casual about \"the collectors thin out after the third gate\"—make it clear this isn't a single toll but a chain, each one bleeding more days.",
    "stance": "dread"
  },
  {
    "outcome": "Haro's hand rests on the sealed crate a moment longer, and he tells Wren: \"Your sender knew this seal would hold. Knew I'd stop at inspection. That's why you're worth nine days instead of opening this here.\" Wren realizes the fee is a bargain and the cargo is someone's deliberate choice of his route.",
    "stance": "hope"
  },
  {
    "outcome": "Wren pays, repacks, and crosses. Three miles past the gate the crate's binding catches on overhanging stone and tears. By the time Wren sets the frame down to inspect, the seal is compromised and the contents—whatever they are—have shifted or spilled. He has to backtrack or go forward with broken cargo.",
    "stance": "neither"
  }
]

[
  {
    "outcome": "Wren pays Haro the 9 days, accepts the toll, and shoulders the crate again to pass through the Ferrous Gate into whatever lies beyond.",
    "stance": "neither"
  },
  {
    "outcome": "Wren refuses the toll or cannot pay it, sets the crate down, and attempts to walk around the gate to avoid the debt—but the System catches the circumvention and marks a penalty far worse than nine days.",
    "stance": "dread"
  },
  {
    "outcome": "Haro breaks the wax seal and opens the crate, and Wren sees for the first time what he has been hauling on his back since the low bridges.",
    "stance": "hope"
  }
]

[
  {
    "outcome": "Wren accepts the nine-day toll and hoists the crate onto his frame to pass through the Ferrous Gate, watching Haro write the entry in his ledger and add 9 days to his running total.",
    "stance": "neither"
  },
  {
    "outcome": "Haro's fingers find the seal is already cracked at its edge; he pries the crate open and discovers the contents have shifted inside, and he declares additional charges for 'compromised goods.'",
    "stance": "dread"
  },
  {
    "outcome": "Wren shoulders the crate but pauses to ask Haro quietly whether the debt ever ends, and Haro looks down at his ledger without answering, just turns a page.",
    "stance": "dread"
  }
]

[
  {"outcome": "Wren pays the 9 days, picks up the crate, and passes through the Ferrous Gate to continue down the Road.", "stance": "neither"},
  {"outcome": "Wren refuses the toll and walks around the gate; the Road's System records the violation and adds a penalty larger than 9 days to his ledger.", "stance": "dread"},
  {"outcome": "Haro breaks the wax seal on the crate and opens it to see what Wren is carrying.", "stance": "hope"}
]

[
  {
    "outcome": "Wren records the 9-day toll in Haro's ledger, reloads his sealed crate, and passes through the Ferrous Gate to continue down the Road.",
    "stance": "neither"
  },
  {
    "outcome": "Wren refuses to pay nine days and walks around the Ferrous Gate rather than accept Haro's charge. The Road immediately registers this evasion as greater debt, costing him far more than if he had simply capitulated.",
    "stance": "dread"
  },
  {
    "outcome": "Haro breaks the wax seal and forces open the carefully-packed crate to inspect its mysterious contents, exposing whatever has remained sealed and intact since the low bridges.",
    "stance": "dread"
  }
]

[
  {
    "outcome": "Wren removes a small carved token from his pack and hands it to Haro. Haro checks the ledger, makes a mark against Wren's name, and nods. Wren shoulders the crate and walks through the Ferrous Gate into the haze.",
    "stance": "hope"
  },
  {
    "outcome": "Haro draws a small iron tool from his pocket and looks at the wax seal on the crate. He says, 'Show me what's inside it, or the discretion fee is five more days, not two.' Wren's hand moves toward the seal but stops.",
    "stance": "dread"
  },
  {
    "outcome": "A second figure emerges from behind Wren on the Road, walking fast in a grey gate-keeper's coat. They hand Haro a different ledger, smaller and older, marked with a sigil Wren recognizes. Haro's face goes neutral, and he looks at Wren again.",
    "stance": "hope"
  }
]

[
  {"outcome": "Wren accepts the nine-day toll and the gate opens. He continues down the Road with the crate still sealed, his debt deepened.", "stance": "neither"},
  {"outcome": "Haro breaks the wax seal and opens the crate to inspect its contents. He closes it and returns it to Wren without comment.", "stance": "dread"},
  {"outcome": "Wren refuses the nine-day toll, picks up the crate, and walks around the Ferrous Gate. The Road marks him with additional debt for circumventing the toll.", "stance": "dread"}
]

[
  {"outcome": "Wren pays Haro the 9 days, ties the sealed crate back onto his frame, and walks on down the Road.", "stance": "neither"},
  {"outcome": "Haro reaches past the seal, opens the pale wooden crate, and looks at what is packed inside.", "stance": "dread"},
  {"outcome": "Wren turns his frame away from the Ferrous Gate, walks around it to avoid the toll, and the Road records the violation as a debt worse than 9 days.", "stance": "dread"}
]

